function PerplexityResponseView(props) {
  const response = props.data;
  if (!response) return null;

  const content = response.choices[0]?.message.content;
  const citations = response.citations;

  // Link icon SVG
  function LinkIcon() {
    return React.createElement('svg', {
      width: '10',
      height: '10',
      viewBox: '0 0 16 16',
      fill: 'none',
      style: { color: '#64748b' }
    }, [
      React.createElement('path', {
        key: 'p1',
        d: 'M6.5 9.5L9.5 6.5',
        stroke: 'currentColor',
        strokeWidth: '1.5',
        strokeLinecap: 'round',
        strokeLinejoin: 'round'
      }),
      React.createElement('path', {
        key: 'p2',
        d: 'M4.5 7.5L3 9C2.17157 9.82843 2.17157 11.1716 3 12C3.82843 12.8284 5.17157 12.8284 6 12L7.5 10.5',
        stroke: 'currentColor',
        strokeWidth: '1.5',
        strokeLinecap: 'round',
        strokeLinejoin: 'round'
      }),
      React.createElement('path', {
        key: 'p3',
        d: 'M8.5 5.5L10 4C10.8284 3.17157 12.1716 3.17157 13 4C13.8284 4.82843 13.8284 6.17157 13 7L11.5 8.5',
        stroke: 'currentColor',
        strokeWidth: '1.5',
        strokeLinecap: 'round',
        strokeLinejoin: 'round'
      })
    ]);
  }

  const styles = {
    container: {backgroundColor: '#ffffff',
padding: '12px',
      'borderRadius': '4px',
            display: 'flex',
      flexDirection: 'column',
      gap: '16px',
      fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif'
    },
    content: {
      maxWidth: 'none',
      lineHeight: '1.5',
      color: '#1e293b'
    },
    citationsContainer: {
      display: 'flex',
      flexWrap: 'wrap',
      gap: '10px',
      width: '100%'
    },
    cardWrapper: {
      width: 'calc(33.33% - 7px)',
      minWidth: '180px',
      boxSizing: 'border-box'
    },
    citationCard: {
      position: 'relative',
      borderRadius: '6px',
      border: '1px solid #e2e8f0',
      backgroundColor: '#ffffff',
      padding: '6px 10px',
      marginBottom: '6px',
      width: '100%',
      boxSizing: 'border-box',
      cursor: 'pointer',
      transition: 'background-color 0.2s ease-in-out'
    },
    cardHover: {
      backgroundColor: '#f8fafc'
    },
    titleContainer: {
      display: 'flex',
      alignItems: 'center',
      gap: '2px'
    },
    title: {
      fontWeight: '500',
      color: '#1e293b',
      overflow: 'hidden',
      textOverflow: 'ellipsis',
      whiteSpace: 'nowrap',
      fontSize: '13px',
      margin: 0
    },
    subtitle: {
      fontSize: '11px',
      color: '#64748b',
      overflow: 'hidden',
      textOverflow: 'ellipsis',
      whiteSpace: 'nowrap',
      marginTop: '3px',
      margin: 0
    },
    externalLink: {
      color: '#64748b',
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      marginRight: '3px',
      textDecoration: 'none',
      flexShrink: 0
    },
    sup: {
      fontSize: '10px',
      fontWeight: '500',
      verticalAlign: 'super',
      color: '#0284c7',
      cursor: 'pointer',
      padding: '0 1px'
    },
    citationIndex: {
      display: 'inline-block',
      minWidth: '18px',
      height: '18px',
      lineHeight: '18px',
      textAlign: 'center',
      backgroundColor: '#0284c7',
      color: 'white',
      borderRadius: '4px',
      fontSize: '10px',
      fontWeight: 'bold',
      marginRight: '6px'
    }
  };

  // Process content to add citation references
  const processCitationsInText = (text) => {
    if (!text || !citations || citations.length === 0) return text;

    // For now, we'll just add citation references at the end of paragraphs
    // In a real implementation, you would need a more sophisticated approach to place citations where they belong
    const paragraphs = text.split('\n\n');
    let citationIndex = 0;

    return paragraphs.map((paragraph, i) => {
      // Add a citation reference to every other paragraph for this example
      // In a real implementation, you would determine where citations belong based on content
      if (i % 2 === 0 && citationIndex < citations.length) {
        const supElement = `<sup style="font-size: 10px; font-weight: 500; vertical-align: super; color: #0284c7;">[${citationIndex + 1}]</sup>`;
        citationIndex++;
        return paragraph + ' ' + supElement;
      }
      return paragraph;
    }).join('\n\n');
  };

  // Full markdown formatting
  const formatMarkdown = (text) => {
    if (!text) return '';

    // First process citations
    let processedText = processCitationsInText(text);

    // Format headers
    let formatted = processedText.replace(/^# (.+)$/gm, '<h1 style="font-size: 24px; font-weight: bold; margin: 16px 0;">$1</h1>');
    formatted = formatted.replace(/^## (.+)$/gm, '<h2 style="font-size: 20px; font-weight: 600; margin: 12px 0;">$1</h2>');
    formatted = formatted.replace(/^### (.+)$/gm, '<h3 style="font-size: 18px; font-weight: 500; margin: 8px 0;">$1</h3>');

    // Format lists
    formatted = formatted.replace(/^\* (.+)$/gm, '<li style="margin-left: 16px; margin-bottom: 4px;">$1</li>');
    formatted = formatted.replace(/^\d+\. (.+)$/gm, '<li style="margin-left: 16px; margin-bottom: 4px;">$1</li>');

    // Format paragraphs (but preserve existing HTML tags like sup)
    formatted = formatted.replace(/^(?!<h|<li|<sup)(.+)$/gm, '<p style="margin: 8px 0;">$1</p>');

    // Format bold and italic
    formatted = formatted.replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>');
    formatted = formatted.replace(/\*(.+?)\*/g, '<em>$1</em>');

    return formatted;
  };

  // Extract domain name and get a clean title from URL
  const getSourceTitle = (url) => {
    try {
      const urlObj = new URL(url);
      const hostname = urlObj.hostname;

      // Remove www. prefix if present
      let title = hostname.replace(/^www\./, '');

      // Split by dots and get the main domain name
      const parts = title.split('.');
      if (parts.length >= 2) {
        // Use the main domain name (e.g., 'nature' from 'nature.com')
        return parts[0].charAt(0).toUpperCase() + parts[0].slice(1);
      }

      return title;
    } catch (e) {
      // If URL parsing fails, return a portion of the original string
      return url.substring(0, 20) + '...';
    }
  };

  // Truncate URL for display
  const getTruncatedUrl = (url) => {
    try {
      const urlObj = new URL(url);
      const path = urlObj.pathname;

      // Truncate path if too long
      if (path.length > 25) {
        return urlObj.origin + path.substring(0, 25) + '...';
      }

      return url;
    } catch (e) {
      return url.substring(0, 35) + (url.length > 35 ? '...' : '');
    }
  };

  // Handle clicking on a citation card
  const handleCitationClick = (url) => {
    window.open(url, '_blank', 'noopener,noreferrer');
  };

  return React.createElement('div', { style: styles.container },
    // Main content with full markdown
    React.createElement('div', { 
      style: styles.content,
      dangerouslySetInnerHTML: { __html: formatMarkdown(content) }
    }),

    // Citations as cards in a grid layout (3 per row)
    citations && citations.length > 0 && React.createElement('div', { style: styles.citationsContainer },
      citations.map((citation, index) => {
        const sourceTitle = getSourceTitle(citation);
        const truncatedUrl = getTruncatedUrl(citation);

        return React.createElement('div', { key: index, style: styles.cardWrapper },
          React.createElement('div', { 
            style: styles.citationCard,
            onClick: () => handleCitationClick(citation),
            onMouseEnter: (e) => {
              e.currentTarget.style.backgroundColor = '#f8fafc';
            },
            onMouseLeave: (e) => {
              e.currentTarget.style.backgroundColor = '#ffffff';
            }
          },
            React.createElement('div', { style: styles.titleContainer },
              React.createElement('span', { style: styles.citationIndex }, `${index + 1}`),
              React.createElement('h3', { style: styles.title }, sourceTitle)
            ),
            React.createElement('p', { style: styles.subtitle }, truncatedUrl)
          )
        );
      })
    )
  );
}
